streaks_help_drops={fr="Nombre de fois ou cet objet a deja drop sur ce monstre, avec cet ID, cette difficulte et cet episode (d'apres l'historique).",en="Number of times this item already dropped from this monster with this ID, difficulty and episode (from the history).",ja="このID・難易度・エピソードで、このモンスターからこのアイテムが既にドロップした回数 (履歴より)。"},
streaks_help_total={fr="Monstres de ce type tues avec cet ID, la difficulte et l'episode choisis,\ndepuis le debut du suivi de l'addon.",en="Monsters of this type killed with this ID, difficulty and episode,\nsince the addon started tracking.",ja="選択したID・難易度・エピソードで倒したこの種類のモンスターの数\n(アドオンが記録を開始してからの合計)。"},
streaks_help_since={fr="Kills de ce monstre depuis le dernier drop de son objet rare\n(ou depuis le debut du suivi s'il n'a jamais drop).",en="Kills of this monster since the last drop of its rare item\n(or since tracking started if it never dropped).",ja="このモンスターのレアアイテムが最後にドロップしてからのキル数\n(一度もドロップしていない場合は記録開始から)。"},
streaks_help_expected={fr="Nombre moyen de kills necessaires pour obtenir l'objet :\nun taux de 1/N donne N. Calcule avec le DAR et le RDR de la partie.",en="Average number of kills needed to get the item:\na 1/N rate gives N. Computed with the game's DAR and RDR.",ja="アイテムを入手するのに必要な平均キル数:\n確率 1/N なら N。ゲームのDARとRDRから計算します。"},
streaks_help_ratio={fr="Ecart = Kills sans drop / Attendu.\nx1 : tu es pile dans la moyenne.\nx2,5 : 2,5 fois plus de kills que la moyenne sans drop (longue serie).\nx0,3 : il est encore tot.",en="Ratio = Kills without drop / Expected.\nx1: you are exactly on average.\nx2.5: 2.5 times more kills than average without a drop (long streak).\nx0.3: it is still early.",ja="差 = ドロップなしのキル数 / 期待値。\nx1: ちょうど平均。\nx2.5: 平均の2.5倍キルしても未ドロップ (長い連続)。\nx0.3: まだ序盤です。"},
luck_expected={fr="Attendu en moyenne : %s kills",en="Expected on average: %s kills",ja="平均の期待値: %s キル"},
luck_good={fr="Chance : moins de kills que prevu",en="Lucky: fewer kills than expected",ja="幸運: 期待より少ないキル数"},
